after.content:
if (inbound.hasDeviceChallengeResponse() && deviceChallenges != null) {
    var response = inbound.getDeviceChallengeResponse();
    state.principal = deviceChallenges.verify(inbound.getConnectionId(), response.getDeviceId(),
            response.getDeviceId(), response.getDeviceAuthAlgorithm(), "direct", "",
            response.getNonce().toByteArray(), response.getSignature().toByteArray());
    state.authenticated = true;
